index abf1870..3941174 100644
--- a/src/runner/workflow.rs
+++ b/src/runner/workflow.rs
@@ -409,6 +409,29 @@ impl<'a> WorkflowRunner<'a> {
                 }
             }

+            // Dry-run mode: show what would be executed and skip to next step
+            if options.dry_run {
+                ui.message(&step_display);
+                let command = crate::config::interpolation::resolve_string(&step.command, context)
+                    .unwrap_or_else(|_| step.command.clone());
+                ui.message(&format!("    Would run: {}", command));
+                if !step.env.is_empty() {
+                    let mut env_keys: Vec<_> = step.env.keys().collect();
+                    env_keys.sort();
+                    for key in env_keys {
+                        ui.message(&format!("    {}={}", key, step.env.get(key).unwrap()));
+                    }
+                }
+                results.push(StepResult::success(
+                    &step.name,
+                    Duration::ZERO,
+                    None,
+                    Some(format!("Would run: {}", command)),
+                ));
+                ui.show_workflow_progress(index + 1, total, start.elapsed());
+                continue;
+            }
+
             // Resolve effective prompt_if_complete (step-level, possibly overridden)
             let effective_prompt_if_complete = step_overrides
                 .get(step_name)
@@ -3860,4 +3883,292 @@ mod tests {
         let cycle = graph.find_cycle();
         assert!(cycle.is_some());
     }
+
+    #[test]
+    fn run_with_ui_dry_run_shows_would_run() {
+        let temp = TempDir::new().unwrap();
+        let marker = temp.path().join("should_not_exist.txt");
+
+        let config: BivvyConfig = serde_yaml::from_str(
+            r#"
+            workflows:
+              default:
+                steps: [install]
+        "#,
+        )
+        .unwrap();
+
+        let mut steps = HashMap::new();
+        steps.insert(
+            "install".to_string(),
+            make_step("install", &format!("touch {}", marker.display()), vec![]),
+        );
+
+        let runner = WorkflowRunner::new(&config, steps);
+        let options = RunOptions {
+            dry_run: true,
+            ..Default::default()
+        };
+        let ctx = InterpolationContext::new();
+        let mut ui = MockUI::new();
+
+        let result = runner
+            .run_with_ui(
+                &options,
+                &ctx,
+                &HashMap::new(),
+                temp.path(),
+                false,
+                &HashMap::new(),
+                None,
+                &mut ui,
+            )
+            .unwrap();
+
+        assert!(result.success);
+        assert!(!marker.exists(), "dry-run should not execute commands");
+        assert!(
+            ui.messages().iter().any(|m| m.contains("Would run:")),
+            "dry-run should show 'Would run:' message, got: {:?}",
+            ui.messages()
+        );
+    }
+
+    #[test]
+    fn run_with_ui_dry_run_shows_step_command() {
+        let temp = TempDir::new().unwrap();
+
+        let config: BivvyConfig = serde_yaml::from_str(
+            r#"
+            workflows:
+              default:
+                steps: [deps]
+        "#,
+        )
+        .unwrap();
+
+        let mut steps = HashMap::new();
+        steps.insert("deps".to_string(), make_step("deps", "npm install", vec![]));
+
+        let runner = WorkflowRunner::new(&config, steps);
+        let options = RunOptions {
+            dry_run: true,
+            ..Default::default()
+        };
+        let ctx = InterpolationContext::new();
+        let mut ui = MockUI::new();
+
+        runner
+            .run_with_ui(
+                &options,
+                &ctx,
+                &HashMap::new(),
+                temp.path(),
+                false,
+                &HashMap::new(),
+                None,
+                &mut ui,
+            )
+            .unwrap();
+
+        assert!(
+            ui.messages().iter().any(|m| m.contains("npm install")),
+            "dry-run should display the command, got: {:?}",
+            ui.messages()
+        );
+    }
+
+    #[test]
+    fn run_with_ui_dry_run_multiple_steps_shows_all() {
+        let temp = TempDir::new().unwrap();
+
+        let config: BivvyConfig = serde_yaml::from_str(
+            r#"
+            workflows:
+              default:
+                steps: [first, second]
+        "#,
+        )
+        .unwrap();
+
+        let mut steps = HashMap::new();
+        steps.insert(
+            "first".to_string(),
+            make_step("first", "echo step-one", vec![]),
+        );
+        steps.insert(
+            "second".to_string(),
+            make_step("second", "echo step-two", vec![]),
+        );
+
+        let runner = WorkflowRunner::new(&config, steps);
+        let options = RunOptions {
+            dry_run: true,
+            ..Default::default()
+        };
+        let ctx = InterpolationContext::new();
+        let mut ui = MockUI::new();
+
+        let result = runner
+            .run_with_ui(
+                &options,
+                &ctx,
+                &HashMap::new(),
+                temp.path(),
+                false,
+                &HashMap::new(),
+                None,
+                &mut ui,
+            )
+            .unwrap();
+
+        assert!(result.success);
+        assert!(
+            ui.messages().iter().any(|m| m.contains("echo step-one")),
+            "should show first step command"
+        );
+        assert!(
+            ui.messages().iter().any(|m| m.contains("echo step-two")),
+            "should show second step command"
+        );
+    }
+
+    #[test]
+    fn run_with_ui_dry_run_no_spinner_created() {
+        let temp = TempDir::new().unwrap();
+
+        let config: BivvyConfig = serde_yaml::from_str(
+            r#"
+            workflows:
+              default:
+                steps: [hello]
+        "#,
+        )
+        .unwrap();
+
+        let mut steps = HashMap::new();
+        steps.insert("hello".to_string(), make_step("hello", "echo hi", vec![]));
+
+        let runner = WorkflowRunner::new(&config, steps);
+        let options = RunOptions {
+            dry_run: true,
+            ..Default::default()
+        };
+        let ctx = InterpolationContext::new();
+        let mut ui = MockUI::new();
+
+        runner
+            .run_with_ui(
+                &options,
+                &ctx,
+                &HashMap::new(),
+                temp.path(),
+                false,
+                &HashMap::new(),
+                None,
+                &mut ui,
+            )
+            .unwrap();
+
+        assert!(
+            ui.spinners().is_empty(),
+            "dry-run should not create spinners, got: {:?}",
+            ui.spinners()
+        );
+    }
+
+    #[test]
+    fn run_with_ui_dry_run_skips_interactive_prompts() {
+        let temp = TempDir::new().unwrap();
+
+        let config: BivvyConfig = serde_yaml::from_str(
+            r#"
+            workflows:
+              default:
+                steps: [hello]
+        "#,
+        )
+        .unwrap();
+
+        let mut steps = HashMap::new();
+        steps.insert("hello".to_string(), make_step("hello", "echo hi", vec![]));
+
+        let runner = WorkflowRunner::new(&config, steps);
+        let options = RunOptions {
+            dry_run: true,
+            ..Default::default()
+        };
+        let ctx = InterpolationContext::new();
+        let mut ui = MockUI::new();
+        ui.set_interactive(true);
+
+        runner
+            .run_with_ui(
+                &options,
+                &ctx,
+                &HashMap::new(),
+                temp.path(),
+                false,
+                &HashMap::new(),
+                None,
+                &mut ui,
+            )
+            .unwrap();
+
+        assert!(
+            ui.prompts_shown().is_empty(),
+            "dry-run should not show prompts, got: {:?}",
+            ui.prompts_shown()
+        );
